#ifndef KERNEL_H
#define KERNEL_H

#include <ap_fixed.h>
#include <ap_int.h>
#include <hls_math.h>

// ---- Type definitions from params.yaml ----
// acm / A: bits=22, signed=1, complex=1, fraction=0
// bits_per_component = 22 + 1 = 23
typedef ap_fixed<23, 23> acm_t;

// eigenvalues: bits=22, signed=1, complex=1, fraction=0
// bits_per_component = 23
typedef ap_fixed<23, 23> eval_t;

// eigenvectors: bits=22, signed=1, complex=1, fraction=20
// bits_per_component = 23, integer bits = 23 - 20 = 3
typedef ap_fixed<23, 3> evec_t;

// max_iter / ite: bits=16, signed=0, complex=0, fraction=0
typedef ap_uint<16> iter_t;

static const int N = 10;

// Complex structs
struct acm_complex  { acm_t  re; acm_t  im; };
struct eval_complex { eval_t re; eval_t im; };
struct evec_complex { evec_t re; evec_t im; };

// Top-level kernel
void kernel_top(
    acm_complex  A_in[N][N],
    iter_t       max_iter,
    eval_complex eigenvalues[N],
    evec_complex eigenvectors[N][N],
    iter_t      &ite
);

#endif // KERNEL_H
