#include "kernel.h"
#include <hls_math.h>

// Use double internally for transcendental math, then cast back
// (HLS will synthesise using its cordic/math library)

void kernel_top(
    acm_complex  A_in[N][N],
    iter_t       max_iter,
    eval_complex eigenvalues[N],
    evec_complex eigenvectors[N][N],
    iter_t      &ite
)
{
#pragma HLS INTERFACE ap_ctrl_hs port=return
#pragma HLS ARRAY_PARTITION variable=A_in complete dim=0
#pragma HLS ARRAY_PARTITION variable=eigenvalues complete dim=1
#pragma HLS ARRAY_PARTITION variable=eigenvectors complete dim=0

    // Working arrays in double for numerical accuracy
    double Ar[N][N], Ai[N][N];
    double Vr[N][N], Vi[N][N];

    // Copy input A and initialise V = eye(N)
    INIT_COPY:
    for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
            Ar[i][j] = (double)A_in[i][j].re;
            Ai[i][j] = (double)A_in[i][j].im;
            Vr[i][j] = (i == j) ? 1.0 : 0.0;
            Vi[i][j] = 0.0;
        }
    }

    int z = 0;

    JACOBI_OUTER:
    for (int iter = 0; iter < (int)max_iter; iter++) {
#pragma HLS PIPELINE off

        // ---- Find largest off-diagonal element ----
        double off_diag_max = 0.0;
        int p = 0, q = 1;

        FIND_MAX_I:
        for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
            FIND_MAX_J:
            for (int j = i + 1; j < N; j++) {
#pragma HLS UNROLL
                double re = Ar[i][j];
                double im = Ai[i][j];
                double mag = hls::sqrt(re*re + im*im);
                if (mag > off_diag_max) {
                    off_diag_max = mag;
                    p = i;
                    q = j;
                }
            }
        }

        if (off_diag_max < 1e-8) {
            z = iter;
            break;
        }
        z = iter;

        // ---- Compute Jacobi rotation parameters ----
        double a_pp_r = Ar[p][p];
        double a_qq_r = Ar[q][q];
        double a_pq_r = Ar[p][q];
        double a_pq_i = Ai[p][q];

        double abs_a_pq = hls::sqrt(a_pq_r*a_pq_r + a_pq_i*a_pq_i);

        // theta = 0.5 * arctan(2*|a_pq| / (a_pp - a_qq))
        double denom = a_pp_r - a_qq_r;
        double theta;
        if (hls::fabs(denom) < 1e-15) {
            theta = 3.14159265358979323846 / 4.0; // pi/4
        } else {
            theta = 0.5 * hls::atan(2.0 * abs_a_pq / denom);
        }

        // phi = -angle(a_pq)
        double phi = -hls::atan2(a_pq_i, a_pq_r);

        double cos_th = hls::cos(theta);
        double sin_th = hls::sin(theta);
        double cos_ph = hls::cos(phi);
        double sin_ph = hls::sin(phi);

        // U[p,q] = sin(theta)*exp(-j*phi) = sin_th*(cos_ph - j*sin_ph)
        // U[q,p] = sin(theta)*exp( j*phi) = sin_th*(cos_ph + j*sin_ph)
        // U[p,p] =  cos(theta),  U[q,q] = -cos(theta)
        double Uppr =  cos_th,   Uppi = 0.0;
        double Uqqr = -cos_th,   Uqqi = 0.0;
        double Upqr =  sin_th * cos_ph;
        double Upqi = -sin_th * sin_ph;
        double Uqpr =  sin_th * cos_ph;
        double Uqpi =  sin_th * sin_ph;

        // ---- A = U^H * A * U ----
        // Temp storage for A*U column result
        double tmpAr[N][N], tmpAi[N][N];

        // Step 1: tmp = A * U  (only cols p and q change)
        STEP1_I:
        for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
            STEP1_J:
            for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
                tmpAr[i][j] = Ar[i][j];
                tmpAi[i][j] = Ai[i][j];
            }
            // col p: A[:,p]*U[p,p] + A[:,q]*U[q,p]
            tmpAr[i][p] = Ar[i][p]*Uppr - Ai[i][p]*Uppi
                        + Ar[i][q]*Uqpr - Ai[i][q]*Uqpi;
            tmpAi[i][p] = Ar[i][p]*Uppi + Ai[i][p]*Uppr
                        + Ar[i][q]*Uqpi + Ai[i][q]*Uqpr;
            // col q: A[:,p]*U[p,q] + A[:,q]*U[q,q]
            tmpAr[i][q] = Ar[i][p]*Upqr - Ai[i][p]*Upqi
                        + Ar[i][q]*Uqqr - Ai[i][q]*Uqqi;
            tmpAi[i][q] = Ar[i][p]*Upqi + Ai[i][p]*Upqr
                        + Ar[i][q]*Uqqi + Ai[i][q]*Uqqr;
        }

        // Step 2: A = U^H * tmp  (only rows p and q change)
        // U^H[p,:] -> conj(U[:,p])^T:  U^H[p,p]=conj(Upp), U^H[p,q]=conj(Uqp)
        // U^H[q,:]:                    U^H[q,p]=conj(Upq), U^H[q,q]=conj(Uqq)
        double UhpprR =  Uppr, UhpprI = -Uppi;
        double UhpqrR =  Uqpr, UhpqrI = -Uqpi;
        double UhqprR =  Upqr, UhqprI = -Upqi;
        double UhqqrR =  Uqqr, UhqqrI = -Uqqi;

        STEP2_J:
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
            double old_Ar_pj = tmpAr[p][j], old_Ai_pj = tmpAi[p][j];
            double old_Ar_qj = tmpAr[q][j], old_Ai_qj = tmpAi[q][j];

            // row p = U^H[p,p]*tmp[p,:] + U^H[p,q]*tmp[q,:]
            Ar[p][j] = UhpprR*old_Ar_pj - UhpprI*old_Ai_pj
                     + UhpqrR*old_Ar_qj - UhpqrI*old_Ai_qj;
            Ai[p][j] = UhpprR*old_Ai_pj + UhpprI*old_Ar_pj
                     + UhpqrR*old_Ai_qj + UhpqrI*old_Ar_qj;

            // row q = U^H[q,p]*tmp[p,:] + U^H[q,q]*tmp[q,:]
            Ar[q][j] = UhqprR*old_Ar_pj - UhqprI*old_Ai_pj
                     + UhqqrR*old_Ar_qj - UhqqrI*old_Ai_qj;
            Ai[q][j] = UhqprR*old_Ai_pj + UhqprI*old_Ar_pj
                     + UhqqrR*old_Ai_qj + UhqqrI*old_Ar_qj;
        }

        // Copy unchanged rows back from tmp
        COPY_ROWS:
        for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
            if (i != p && i != q) {
                COPY_COLS:
                for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
                    Ar[i][j] = tmpAr[i][j];
                    Ai[i][j] = tmpAi[i][j];
                }
            }
        }

        // Zero out A[p,q] and A[q,p] explicitly
        Ar[p][q] = 0.0; Ai[p][q] = 0.0;
        Ar[q][p] = 0.0; Ai[q][p] = 0.0;

        // ---- V = V * U  (only cols p and q change) ----
        UPDATE_V:
        for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
            double vp_r = Vr[i][p], vp_i = Vi[i][p];
            double vq_r = Vr[i][q], vq_i = Vi[i][q];

            // new col p = V[:,p]*U[p,p] + V[:,q]*U[q,p]
            Vr[i][p] = vp_r*Uppr - vp_i*Uppi + vq_r*Uqpr - vq_i*Uqpi;
            Vi[i][p] = vp_r*Uppi + vp_i*Uppr + vq_r*Uqpi + vq_i*Uqpr;

            // new col q = V[:,p]*U[p,q] + V[:,q]*U[q,q]
            Vr[i][q] = vp_r*Upqr - vp_i*Upqi + vq_r*Uqqr - vq_i*Uqqi;
            Vi[i][q] = vp_r*Upqi + vp_i*Upqr + vq_r*Uqqi + vq_i*Uqqr;
        }
    }

    // ---- Write outputs ----
    WRITE_EVALS:
    for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
        eigenvalues[i].re = (eval_t)Ar[i][i];
        eigenvalues[i].im = (eval_t)Ai[i][i];
    }

    WRITE_EVECS:
    for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
            eigenvectors[i][j].re = (evec_t)Vr[i][j];
            eigenvectors[i][j].im = (evec_t)Vi[i][j];
        }
    }

    ite = (iter_t)z;
}
