#include <cstdio>
#include <cstdlib>
#include <cmath>
#include "kernel.h"

// IO paths (literal, not computed at runtime)
static const char *IO_DIR  = "/home/mbenton/verilog_rapid_prototyping/conversion_015/eig_10_io/";
static const char *SIM_DIR = "/home/mbenton/verilog_rapid_prototyping/conversion_015/build/sim/";

int main()
{
    // ---- Allocate / declare arrays ----
    acm_complex  A_in[N][N];
    iter_t       max_iter_val;
    eval_complex eigenvalues[N];
    evec_complex eigenvectors[N][N];
    iter_t       ite;

    // ----------------------------------------------------------------
    // Read call index 0: in_A.txt  (complex, shape [10,10] → 100 pairs)
    // ----------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sin_A.txt", IO_DIR);
        FILE *fp = fopen(path, "r");
        if (!fp) { fprintf(stderr, "Cannot open %s\n", path); return 1; }

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                double re = 0.0, im = 0.0;
                if (fscanf(fp, "%lf %lf", &re, &im) != 2) {
                    fprintf(stderr, "Parse error in %s at [%d,%d]\n", path, i, j);
                    fclose(fp); return 1;
                }
                A_in[i][j].re = (acm_t)re;
                A_in[i][j].im = (acm_t)im;
            }
        }
        fclose(fp);
    }

    // ----------------------------------------------------------------
    // Read call index 0: in_max_iter.txt  (scalar, 1 value per call)
    // ----------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sin_max_iter.txt", IO_DIR);
        FILE *fp = fopen(path, "r");
        if (!fp) { fprintf(stderr, "Cannot open %s\n", path); return 1; }

        long long mv = 0;
        if (fscanf(fp, "%lld", &mv) != 1) {
            fprintf(stderr, "Parse error in %s\n", path);
            fclose(fp); return 1;
        }
        max_iter_val = (iter_t)(unsigned long long)mv;
        fclose(fp);
    }

    // ----------------------------------------------------------------
    // Invoke kernel
    // ----------------------------------------------------------------
    kernel_top(A_in, max_iter_val, eigenvalues, eigenvectors, ite);

    // ----------------------------------------------------------------
    // Write out_0.txt  (eigenvalues, complex, shape [10])
    // ----------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sout_0.txt", SIM_DIR);
        FILE *fp = fopen(path, "w");
        if (!fp) { fprintf(stderr, "Cannot open %s\n", path); return 1; }

        for (int i = 0; i < N; i++) {
            fprintf(fp, "%.17g %.17g\n",
                    (double)eigenvalues[i].re,
                    (double)eigenvalues[i].im);
        }
        fclose(fp);
    }

    // ----------------------------------------------------------------
    // Write out_1.txt  (eigenvectors, complex, shape [10,10])
    // ----------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sout_1.txt", SIM_DIR);
        FILE *fp = fopen(path, "w");
        if (!fp) { fprintf(stderr, "Cannot open %s\n", path); return 1; }

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                fprintf(fp, "%.17g %.17g\n",
                        (double)eigenvectors[i][j].re,
                        (double)eigenvectors[i][j].im);
            }
        }
        fclose(fp);
    }

    // ----------------------------------------------------------------
    // Write out_2.txt  (ite, scalar)
    // ----------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sout_2.txt", SIM_DIR);
        FILE *fp = fopen(path, "w");
        if (!fp) { fprintf(stderr, "Cannot open %s\n", path); return 1; }

        fprintf(fp, "%u\n", (unsigned)ite);
        fclose(fp);
    }

    printf("Simulation complete. ite=%u\n", (unsigned)ite);
    return 0;
}
